// This is literally the entire source code for Redux Thunk middleware!

const thunkMiddleware = (store) => (next) => (action) => {
  // If the action is a FUNCTION (A Thunk)...
  if (typeof action === 'function') {
    // Execute the function, and pass it dispatch and getState!
    return action(store.dispatch, store.getState);
  }

  // If the action is a normal object, just pass it along to the Reducer
  return next(action);
};
